<script setup>
import { onMounted, ref } from 'vue'
import { sheetApi } from '@/services/api'

const metadata = ref({ courses: [], instructors: [], documentTypes: [], academicYears: [] })
const loading = ref(false)
const message = ref('')
const error = ref('')
const fileInput = ref(null)

const emptyForm = () => ({
  title: '',
  fileName: '',
  fileSize: 0,
  fileType: '',
  fileData: '',
  courseId: '',
  documentType: '',
  academicYear: '',
  instructorId: ''
})

const MAX_FILE_BYTES = 20 * 1024 * 1024

const form = ref(emptyForm())

onMounted(async () => {
  try {
    metadata.value = await sheetApi.metadata()
  } catch (err) {
    error.value = err.message
  }
})

function onFileChange(event) {
  error.value = ''
  const file = event.target.files?.[0]
  if (!file) return
  if (file.size > MAX_FILE_BYTES) {
    error.value = 'File is too large (max 20 MB).'
    event.target.value = ''
    form.value.fileName = ''
    form.value.fileSize = 0
    form.value.fileType = ''
    form.value.fileData = ''
    return
  }
  form.value.fileName = file.name
  form.value.fileSize = file.size
  form.value.fileType = file.type || 'application/octet-stream'
  form.value.fileData = ''
  const reader = new FileReader()
  reader.onload = () => {
    form.value.fileData = String(reader.result).split(',')[1] ?? ''
  }
  reader.onerror = () => {
    error.value = 'Could not read the selected file.'
    form.value.fileData = ''
  }
  reader.readAsDataURL(file)
  if (!form.value.title) form.value.title = file.name.replace(/\.[^.]+$/, '')
}

async function submitUpload() {
  error.value = ''
  message.value = ''
  if (!form.value.fileData) {
    error.value = 'Please choose a file to upload.'
    return
  }
  loading.value = true
  try {
    const request = await sheetApi.createUploadRequest(form.value)
    message.value = `"${request.fileName}" was submitted and is now waiting for administrator approval.`
    form.value = emptyForm()
    if (fileInput.value) fileInput.value.value = ''
  } catch (err) {
    error.value = err.message
  } finally {
    loading.value = false
  }
}
</script>

<template>
  <section class="page-panel upload-flow">
    <div class="panel__header">
      <div>
        <p class="eyebrow">Upload</p>
        <h1>Upload</h1>
        <p>Fill in your document details and submit. Your upload will be sent to an administrator for approval.</p>
      </div>
    </div>

    <div v-if="message" class="form-success">{{ message }}</div>
    <div v-if="error" class="form-error">{{ error }}</div>

    <form class="form request-form" @submit.prevent="submitUpload">
      <label>
        File
        <input ref="fileInput" type="file" required @change="onFileChange" />
      </label>
      <label>
        Document title
        <input v-model="form.title" required placeholder="Algorithm summary" />
      </label>
      <div class="form-grid">
        <label>
          Course
          <select v-model="form.courseId" required>
            <option value="" disabled>Select course</option>
            <option v-for="course in metadata.courses" :key="course.id" :value="course.id">
              {{ course.name }}
            </option>
          </select>
        </label>
        <label>
          Document type
          <select v-model="form.documentType" required>
            <option value="" disabled>Select document type</option>
            <option v-for="type in metadata.documentTypes" :key="type" :value="type">{{ type }}</option>
          </select>
        </label>
        <label>
          Academic year
          <select v-model="form.academicYear" required>
            <option value="" disabled>Select year</option>
            <option v-for="year in metadata.academicYears" :key="year" :value="year">{{ year }}</option>
          </select>
        </label>
        <label>
          Instructor
          <select v-model="form.instructorId" required>
            <option value="" disabled>Select instructor</option>
            <option v-for="instructor in metadata.instructors" :key="instructor.id" :value="instructor.id">
              {{ instructor.name }}
            </option>
          </select>
        </label>
      </div>
      <button class="button button--primary" :disabled="loading" type="submit">Submit Upload</button>
    </form>
  </section>
</template>
